import { S3Client } from 'bun'
import { mkdir, unlink } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { env } from './env'

/** Where processed photos live. Keys are generated by the server (never from user input). */
export interface Store {
  put(key: string, bytes: Uint8Array): Promise<void>
  get(key: string): Promise<Uint8Array | null>
  remove(key: string): Promise<void>
}

const s3Ready = !!(env.s3.endpoint && env.s3.bucket && env.s3.accessKeyId && env.s3.secretAccessKey)

/** Uploads are available with a bucket configured, or anywhere except production (local disk). */
export const photosEnabled = s3Ready || !env.isProd

function s3Store(): Store {
  const client = new S3Client({ endpoint: env.s3.endpoint, bucket: env.s3.bucket, accessKeyId: env.s3.accessKeyId, secretAccessKey: env.s3.secretAccessKey, region: env.s3.region, virtualHostedStyle: env.s3.virtualHosted })
  return {
    put: async (key, bytes) => { await client.file(key).write(bytes, { type: 'image/webp' }) },
    get: async (key) => { const f = client.file(key); return (await f.exists()) ? await f.bytes() : null },
    remove: async (key) => { try { await client.file(key).delete() } catch { /* already gone */ } },
  }
}

function diskStore(): Store {
  const root = resolve(env.uploadDir)
  const path = (key: string) => {
    const p = resolve(join(root, key))
    if (!p.startsWith(root + '/')) throw new Error('bad storage key') // keys are server-made, but never trust a path
    return p
  }
  return {
    put: async (key, bytes) => { await mkdir(dirname(path(key)), { recursive: true }); await Bun.write(path(key), bytes) },
    get: async (key) => { const f = Bun.file(path(key)); return (await f.exists()) ? await f.bytes() : null },
    remove: async (key) => { try { await unlink(path(key)) } catch { /* already gone */ } },
  }
}

export const store: Store = s3Ready ? s3Store() : diskStore()
